+        Assertions.assertThrows(exceptionClass, () -> cachedConnectors.getConnector("invalid", range));
+
+        Assertions.assertThrows(exceptionClass, () -> cachedConnectors.getConnector("invalid", range));
+        verify(plugin, times(1)).newConnector("invalid", range);
+    }
